CREATE TYPE "timesheets"."invoice_status" AS ENUM('DRAFT', 'ISSUED', 'PAID', 'VOID');
CREATE TABLE "timesheets"."invoice" ("id" text PRIMARY KEY, "organization_id" text NOT NULL REFERENCES "organization"("id") ON DELETE cascade, "client_organization_id" text REFERENCES "organization"("id") ON DELETE restrict, "number" text NOT NULL, "status" "timesheets"."invoice_status" DEFAULT 'DRAFT' NOT NULL, "currency" text NOT NULL, "issue_date" date NOT NULL, "due_date" date NOT NULL, "subject" text, "notes" text, "sender_name" text NOT NULL, "sender_address" text NOT NULL, "sender_registration" text, "sender_vat_number" text, "sender_iban" text, "sender_bic" text, "recipient_name" text NOT NULL, "recipient_address" text NOT NULL, "recipient_contact_name" text, "recipient_email" text, "created_by_id" text NOT NULL REFERENCES "user"("id") ON DELETE restrict, "issued_at" timestamp, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "invoice_org_number_uidx" ON "timesheets"."invoice" ("organization_id", "number");
CREATE INDEX "invoice_org_status_idx" ON "timesheets"."invoice" ("organization_id", "status");
CREATE INDEX "invoice_client_idx" ON "timesheets"."invoice" ("client_organization_id");
CREATE TABLE "timesheets"."invoice_line" ("id" text PRIMARY KEY, "invoice_id" text NOT NULL REFERENCES "timesheets"."invoice"("id") ON DELETE cascade, "position" integer NOT NULL, "description" text NOT NULL, "quantity_milli" integer NOT NULL, "unit" text DEFAULT 'hour' NOT NULL, "unit_price_minor" integer NOT NULL, "vat_rate_basis_points" integer DEFAULT 2100 NOT NULL);
CREATE INDEX "invoice_line_invoice_idx" ON "timesheets"."invoice_line" ("invoice_id");
CREATE TABLE "timesheets"."invoice_time_entry" ("id" text PRIMARY KEY, "invoice_id" text NOT NULL REFERENCES "timesheets"."invoice"("id") ON DELETE cascade, "invoice_line_id" text NOT NULL REFERENCES "timesheets"."invoice_line"("id") ON DELETE cascade, "time_entry_id" text NOT NULL REFERENCES "timesheets"."time_entry"("id") ON DELETE restrict);
CREATE INDEX "invoice_time_entry_entry_idx" ON "timesheets"."invoice_time_entry" ("time_entry_id");
CREATE INDEX "invoice_time_entry_invoice_idx" ON "timesheets"."invoice_time_entry" ("invoice_id");
CREATE TABLE "timesheets"."invoice_payment" ("id" text PRIMARY KEY, "invoice_id" text NOT NULL REFERENCES "timesheets"."invoice"("id") ON DELETE cascade, "paid_on" date NOT NULL, "amount_minor" integer NOT NULL, "reference" text, "note" text, "created_by_id" text NOT NULL REFERENCES "user"("id") ON DELETE restrict, "created_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX "invoice_payment_invoice_idx" ON "timesheets"."invoice_payment" ("invoice_id");
